def page(path,theme,title,desc,body,img,graph):
    url = BASE+path
    active_nav = nav.replace('href="'+path+'"', 'href="'+path+'" aria-current="page"',1) if path != '/404' else nav
    return f'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="{'#ebe8e1' if theme=='home' else '#101116'}"><title>{title}</title><meta name="description" content="{desc}"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:locale" content="fr_CA"><meta property="og:site_name" content="VRTG"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}/assets/{img}"><meta property="og:image:alt" content="{title}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{title}"><meta name="twitter:description" content="{desc}"><meta name="twitter:image" content="{BASE}/assets/{img}"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/site.css"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False)}</script><script src="/site.js" defer></script></head>
<body class="{theme}"><a class="skip-link" href="#main">Aller au contenu</a>{active_nav}<main id="main" tabindex="-1">{body}</main><footer class="footer"><a class="brand" href="/">VRTG</a><span>Musique francophone. Deux univers.</span><span>© 2026 VRTG</span></footer>{player}<div class="sr-only" id="navigation-status" role="status"></div></body></html>'''
for path,theme,title,desc,body,img,graph in [('/', 'home','VRTG — Rap introspectif et musique alternative francophone','Découvrez VRTG, projet musical francophone, et ses deux univers : Fréquences et Fragments. Écoutez les morceaux et retrouvez les plateformes de streaming.',home,'hero-vrtg.webp',[artist,*albums,*tracks,*fragment_tracks]),('/frequences','frequences','Fréquences — VRTG | Écouter les morceaux','Écoutez Fréquence_01, Fréquence_02 et Fréquence_03, les morceaux du projet Fréquences de VRTG. Rap introspectif francophone et imaginaire cosmique.',freq,'cover-frequence-02.webp',[artist,albums[0],*tracks]),('/fragments','fragments','Fragments — VRTG | Écouter Fragment_01, Fragment_02 et Fragment_03','Écoutez Fragment_01, Fragment_02 et Fragment_03 de VRTG. Trois morceaux en français dans un univers intime, nocturne et cinématographique.',frag,'cover-fragments.webp',[artist,albums[1],*fragment_tracks])]:
    dest = ROOT / (path.strip('/')+'/index.html' if path!='/' else 'index.html')
    dest.parent.mkdir(exist_ok=True)
    dest.write_text(page(path,theme,title,desc,body,img,graph))
